import { cardLabel } from './cardBrand'
import { fullName } from './clientName'
import type { ApplicationWithClient } from './useApplications'
import { formatDate, formatSum } from '@/shared/lib/format'
import { formatPassport } from '@/shared/lib/passport'
import { buildTextPdf, downloadBlob } from '@/shared/lib/pdf'

/** Mock contract file. The real document will be generated by the backend. */
// The mock PDF writer only knows plain Latin letters
const plain = (text: string) => text.replace(/[ʻʼ‘’]/g, "'").replace(/•/g, '*')

/** `locationName` is the filial the sale belongs to, already in the reader's language. */
export function downloadContract(
  { application, client }: ApplicationWithClient,
  locationName?: string,
) {
  const { details } = application
  const card = client.cards.find((item) => item.id === details?.cardId)
  const lines = [
    `Birzum nasiya - Shartnoma ${application.contractNumber ?? ''}`,
    '(namuna hujjat)',
    '',
    `Ariza raqami: ${application.id}`,
    `Sana: ${formatDate(application.date)}`,
    ...(locationName ? [`Filial: ${plain(locationName)}`] : []),
    `Klient: ${fullName(client)}`,
    `Pasport: ${formatPassport(client.passport)}`,
    `JSHSHIR: ${client.pinfl}`,
    '',
    ...(details?.products ?? []).map(
      (product) => `${product.name} - ${formatSum(product.price)} x ${product.quantity}`,
    ),
    '',
    `Jami tovarlar summasi: ${formatSum(application.goodsTotal)}`,
    `Muddatli to'lov narxi: ${formatSum(application.installmentTotal)}`,
    ...(details
      ? [
          `Muddat: ${details.term} oy`,
          `Oylik to'lov: ${formatSum(details.monthlyPayment)}`,
          `To'lov sanasi: har oyning ${details.paymentDay}-kuni`,
          ...(card ? [`To'lov kartasi: ${plain(cardLabel(card))}`] : []),
          ...(details.fulfilment
            ? [
                details.fulfilment.method === 'delivery'
                  ? `Qabul qilish: yetkazib berish, ${plain(details.fulfilment.address)}`
                  : "Qabul qilish: do'kondan olib ketish",
              ]
            : []),
        ]
      : []),
  ]
  const name = (application.contractNumber ?? String(application.id)).replace(/[^\w-]/g, '-')
  downloadBlob(buildTextPdf(lines), `shartnoma-${name}.pdf`)
}
